using System;using System.Drawing;using System.Reflection;using System.Windows.Forms;
class CgBrightnessChecks{[STAThread]static void Main(){using(var c=new OpeningCgCanvas("","","")){var f=BindingFlags.Instance|BindingFlags.NonPublic;c.Size=new Size(960,540);var art=new Bitmap(960,540);using(var g=Graphics.FromImage(art))g.Clear(Color.FromArgb(110,150,90));typeof(OpeningCgCanvas).GetField("picture",f).SetValue(c,art);typeof(OpeningCgCanvas).GetField("<FramesShown>k__BackingField",f).SetValue(c,1);typeof(OpeningCgCanvas).GetField("timer",f).SetValue(c,new Timer());int count=0;c.Completed=()=>count++;typeof(OpeningCgCanvas).GetMethod("PlaybackEnded",f).Invoke(c,null);using(var shot=new Bitmap(960,540)){c.DrawToBitmap(shot,c.ClientRectangle);if(shot.GetPixel(480,200).R!=110)throw new Exception("waiting frame dimmed");}typeof(OpeningCgCanvas).GetMethod("OnMouseUp",f).Invoke(c,new object[]{new MouseEventArgs(MouseButtons.Left,1,20,20,0)});if(count!=0)throw new Exception("transition skipped");System.Threading.Thread.Sleep(130);using(var shot=new Bitmap(960,540)){c.DrawToBitmap(shot,c.ClientRectangle);if(shot.GetPixel(480,200).R>=110)throw new Exception("click did not dim frame");}System.Threading.Thread.Sleep(150);typeof(OpeningCgCanvas).GetMethod("TickPlayback",f).Invoke(c,null);if(count!=1)throw new Exception("transition completion missing");}Console.WriteLine("PASS bright waiting frame, dimming only after click, delayed transition once");}}
